block:
{% set accent = options.accent_colour|default(settings.primary_color) %}
<section class="rfx-block">
    <style>
        .rfx-block {
            font-family: system-ui, sans-serif;
            padding: 2rem 1rem;
            background: var(--gray-color-950);
            color: var(--gray-color-50);
        }
        .rfx-block .rfx-grid {
            display: grid;
            gap: 1rem;
            grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
            max-width: 60rem;
            margin: 0 auto;
        }
        .rfx-block article {
            background: var(--gray-color-900);
            border: 1px solid var(--gray-color-800);
            border-radius: 0.75rem;
            padding: 1rem;
        }
        .rfx-block img {
            max-width: 100%;
            border-radius: 0.5rem;
        }
        .rfx-block a {
            display: inline-block;
            margin-top: 0.5rem;
            padding: 0.5rem 1rem;
            border-radius: 0.5rem;
            background: {{ accent }};
            color: {{ settings.button_text_color }};
            text-decoration: none;
        }
    </style>

    <h2 style="text-align: center">{{ options.heading|default('Ending soon') }}</h2>

    {% if competitions.ending_soon|length == 0 %}
    <p style="text-align: center; color: var(--gray-color-400)">
        No competitions are running right now. Check back soon.
    </p>
    {% else %}
    <div class="rfx-grid">
        {% for competition in competitions.ending_soon|slice(0, options.limit|default(3)) %}
        <article>
            <img src="{{ competition.image_url }}" alt="{{ competition.title }}" />
            <h3>{{ competition.title }}</h3>
            {% if options.show_price|default(true) %}
            <p>{{ competition.price }} per ticket · ends {{ competition.end_date }}</p>
            {% endif %}
            <a href="{{ competition.url }}">Enter now</a>
        </article>
        {% endfor %}
    </div>
    {% endif %}
</section>
